 for(const ref of info.importedFiles){if(!ref.fileName.startsWith('.'))continue;const base=path.resolve(path.dirname(file),ref.fileName);if(!base.startsWith(root+path.sep))throw Error('Source outside workspace');const options=[base,base+'.ts',base+'.tsx',base+'.js',path.join(base,'index.ts')];let resolved:string|null=null;for(const candidate of options){try{if((await stat(candidate)).isFile()){resolved=path.relative(root,candidate);break}}catch{}}if(!resolved)throw Error('Unresolved source '+ref.fileName+' in '+file);await walk(resolved)}
};
